import 'package:equatable/equatable.dart'; import 'package:flutter_bloc/flutter_bloc.dart'; import '../../domain/entities/exam_entity.dart'; import '../../domain/repositories/exam_repository.dart';
sealed class ExamEvent extends Equatable { const ExamEvent(); @override List<Object?> get props=>[]; } class LoadExams extends ExamEvent { const LoadExams(); } class SaveExam extends ExamEvent { const SaveExam(this.exam); final ExamEntity exam; @override List<Object> get props=>[exam]; }
sealed class ExamState extends Equatable { const ExamState(); @override List<Object?> get props=>[]; } class ExamInitial extends ExamState { const ExamInitial(); } class ExamLoading extends ExamState { const ExamLoading(); } class ExamLoaded extends ExamState { const ExamLoaded(this.exams); final List<ExamEntity> exams; @override List<Object> get props=>[exams]; } class ExamError extends ExamState { const ExamError(this.message); final String message; @override List<Object> get props=>[message]; }
class ExamBloc extends Bloc<ExamEvent,ExamState>{ ExamBloc(this._repository):super(const ExamInitial()){on<LoadExams>(_load);on<SaveExam>(_save);} final ExamRepository _repository; Future<void> _load(ExamEvent e,Emitter<ExamState> emit)async{emit(const ExamLoading());try{emit(ExamLoaded(await _repository.getExams()));}catch(error){emit(ExamError(error.toString()));}} Future<void> _save(SaveExam e,Emitter<ExamState> emit)async{emit(const ExamLoading());try{await _repository.save(e.exam);emit(ExamLoaded(await _repository.getExams()));}catch(error){emit(ExamError(error.toString()));}}}
